var fnGetGamepadPowerInfo func(gamepad *Gamepad, percent *int32) PowerState

// Get the battery state of a gamepad.
//
// You should never take a battery status as absolute truth. Batteries
// (especially failing batteries) are delicate hardware, and the values
// reported here are best estimates based on what that hardware reports. It's
// not uncommon for older batteries to lose stored power much faster than it
// reports, or completely drain when reporting it has 20 percent left, etc.
//
// Parameters:
//   - gamepad: the gamepad object to query.
//   - percent: a pointer filled in with the percentage of battery life left, between 0 and 100, or NULL to ignore. This will be filled in with -1 we can't determine a value or there is no battery.
//
// Returns: the current battery state.
//
// Thread safety: It is safe to call this function from any thread.
//
// Since: SDL 3.2.0.
func GetGamepadPowerInfo(gamepad *Gamepad, percent *int32) PowerState {
	return fnGetGamepadPowerInfo(gamepad, percent)
}

