var fnGetGamepadAxis func(gamepad *Gamepad, axis GamepadAxis) int16

// Get the current state of an axis control on a gamepad.
//
// The axis indices start at index 0.
//
// For thumbsticks, the state is a value ranging from -32768 (up/left) to
// 32767 (down/right).
//
// Triggers range from 0 when released to 32767 when fully pressed, and never
// return a negative value. Note that this differs from the value reported by
// the lower-level GetJoystickAxis(), which normally uses the full range.
//
// Note that for invalid gamepads or axes, this will return 0. Zero is also a
// valid value in normal operation; usually it means a centered axis.
//
// Parameters:
//   - gamepad: a gamepad.
//   - axis: an axis index (one of the GamepadAxis values).
//
// Returns: axis state.
//
// Thread safety: It is safe to call this function from any thread.
//
// Since: SDL 3.2.0.
//
// See also: GamepadHasAxis, GetGamepadButton
func GetGamepadAxis(gamepad *Gamepad, axis GamepadAxis) int16 {
	return fnGetGamepadAxis(gamepad, axis)
}

