var fnRumbleGamepad func(gamepad *Gamepad, low_frequency_rumble uint16, high_frequency_rumble uint16, duration_ms uint32) bool

// Start a rumble effect on a gamepad.
//
// Each call to this function cancels any previous rumble effect, and calling
// it with 0 intensity stops any rumbling.
//
// This function requires you to process SDL events or call
// UpdateJoysticks() to update rumble state.
//
// Parameters:
//   - gamepad: the gamepad to vibrate.
//   - low_frequency_rumble: the intensity of the low frequency (left) rumble motor, from 0 to 0xFFFF.
//   - high_frequency_rumble: the intensity of the high frequency (right) rumble motor, from 0 to 0xFFFF.
//   - duration_ms: the duration of the rumble effect, in milliseconds.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Thread safety: It is safe to call this function from any thread.
//
// Since: SDL 3.2.0.
func RumbleGamepad(gamepad *Gamepad, low_frequency_rumble uint16, high_frequency_rumble uint16, duration_ms uint32) bool {
	return fnRumbleGamepad(gamepad, low_frequency_rumble, high_frequency_rumble, duration_ms)
}

var fnRumbleGamepadTriggers func(gamepad *Gamepad, left_rumble uint16, right_rumble uint16, duration_ms uint32) bool

// Start a rumble effect in the gamepad's triggers.
//
// Each call to this function cancels any previous trigger rumble effect, and
// calling it with 0 intensity stops any rumbling.
//
// Note that this is rumbling of the _triggers_ and not the gamepad as a
// whole. This is currently only supported on Xbox One gamepads. If you want
// the (more common) whole-gamepad rumble, use RumbleGamepad() instead.
//
// This function requires you to process SDL events or call
// UpdateJoysticks() to update rumble state.
//
// Parameters:
//   - gamepad: the gamepad to vibrate.
//   - left_rumble: the intensity of the left trigger rumble motor, from 0 to 0xFFFF.
//   - right_rumble: the intensity of the right trigger rumble motor, from 0 to 0xFFFF.
//   - duration_ms: the duration of the rumble effect, in milliseconds.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Thread safety: It is safe to call this function from any thread.
//
// Since: SDL 3.2.0.
//
// See also: RumbleGamepad
func RumbleGamepadTriggers(gamepad *Gamepad, left_rumble uint16, right_rumble uint16, duration_ms uint32) bool {
	return fnRumbleGamepadTriggers(gamepad, left_rumble, right_rumble, duration_ms)
}

